<div class="section-head"><div><span class="eyebrow">DATA & PREDIKSI</span><h2>Data Asesmen</h2><p class="muted">Input hasil asesmen untuk menghasilkan rekomendasi AI.</p></div></div><div class="form-card wide"><form method="post"><input type="hidden" name="action" value="add_assessment"><div class="form-row four"><label>Siswa<select name="student_id" required><?php foreach($students as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?> — <?= e($s['class_name']) ?></option><?php endforeach; ?></select></label><label>Mata pelajaran<input name="subject" required placeholder="Matematika"></label><label>Tanggal<input type="date" name="assessment_date" value="<?= date('Y-m-d') ?>" required></label><label>Nilai pengetahuan<input type="number" name="knowledge_score" min="0" max="100" step="0.01" required></label></div><div class="form-row three"><label>Nilai keterampilan<input type="number" name="skill_score" min="0" max="100" step="0.01" required></label><label>Penyelesaian tugas (%)<input type="number" name="assignment_rate" min="0" max="100" step="0.01" value="80" required></label><label>Catatan guru<input name="notes" placeholder="Catatan observasi"></label></div><button class="btn primary" type="submit">Simpan & Analisis dengan AI</button></form></div><div class="table-card"><div class="card-title"><h3>Riwayat asesmen</h3><span class="pill">Random Forest</span></div><table><thead><tr><th>Siswa</th><th>Pelajaran</th><th>Nilai</th><th>Rekomendasi</th><th>Confidence</th><th>Tanggal</th></tr></thead><tbody><?php foreach($assessments as $a): ?><tr><td><b><?= e($a['name']) ?></b><br><small><?= e($a['class_name']) ?></small></td><td><?= e($a['subject']) ?></td><td><b><?= number_format((float)$a['avg_score'],1) ?></b><br><small><?= $a['avg_score']>=75?'Tuntas':'Belum tuntas' ?></small></td><td><span class="badge <?= badgeClass($a['action_label']??'') ?>"><?= e($a['action_label']??'—') ?></span></td><td><?= $a['confidence'] ? number_format((float)$a['confidence'],1).'%' : '—' ?></td><td><?= e($a['assessment_date']) ?></td></tr><?php endforeach; ?></tbody></table></div>